// bench/dwell_robustness.cpp
//
// Does the diagonal vote survive variable dwell time? This is the assumption the whole
// method rests on and it has never been tested.
//
// Every synthetic read in this project so far was generated by walking the reference and
// emitting EXACTLY samples_per_event samples per k-mer. Under that generator a query
// event maps one-to-one onto a reference event by construction, so a true diagonal is
// exact and stays exact for the length of the read. quantise.hpp is honest that this is
// an assumption rather than a finding:
//
//     "segmentation is more faithful and much more expensive, and whether it is worth
//      the cycles is an experiment, not an assumption."
//
// Real pores do not cooperate. Translocation speed varies, so a k-mer is held for a
// variable number of samples, and the quantiser segments at a FIXED width. The moment a
// k-mer occupies 7 or 14 samples instead of 10, the fixed segmentation slips out of phase
// and every subsequent query event is offset against the reference -- which breaks the
// diagonal for the rest of the read. Same failure as the spliced-transcript case already
// measured, except it happens continuously rather than at exon boundaries.
//
// So this sweeps dwell variability and skip rate and reports what survives. Two knobs:
//
//   dwell CV    coefficient of variation of the per-k-mer dwell, lognormal about
//               samples_per_event. 0.0 reproduces the old ideal generator. Published
//               R10 dwell distributions sit roughly in the 0.3-0.5 range.
//   skip rate   probability a k-mer contributes NO samples at all (fast translocation).
//
// Interpretation is deliberately framed around correct-diagonal fraction as well as TPR,
// because the spliced case already showed that accepts can keep happening on the wrong
// diagonal while looking like success.
//
// Usage:
//   mru_dwell_robustness <model.tsv> <reference.fa> [reads] [noise_pA] [chunks]

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <random>
#include <string>
#include <vector>

#include "daemon/diagonal_votes.hpp"
#include "index/batched_probe.hpp"
#include "index/minimizer_index.hpp"
#include "index/quantise.hpp"

namespace {

constexpr float kPaToAdc = 8.0f;
constexpr std::size_t kChunkBases = 180;

int base_code(char c) {
  switch (c) {
    case 'A': case 'a': return 0;
    case 'C': case 'c': return 1;
    case 'G': case 'g': return 2;
    case 'T': case 't': return 3;
    default: return -1;
  }
}

bool load_model_tsv(const std::string& path, std::vector<float>& levels) {
  std::ifstream f(path);
  if (!f) return false;
  levels.clear();
  std::string line;
  while (std::getline(f, line)) {
    const std::size_t tab = line.find('\t');
    if (tab == std::string::npos) continue;
    levels.push_back(std::strtof(line.c_str() + tab + 1, nullptr));
  }
  std::size_t p = 1;
  while (p < levels.size()) p *= 4;
  return !levels.empty() && p == levels.size();
}

bool load_fasta_acgt(const std::string& path, std::string& out) {
  std::ifstream f(path);
  if (!f) return false;
  out.clear();
  std::string line;
  while (std::getline(f, line)) {
    if (!line.empty() && line[0] == '>') continue;
    for (char c : line) {
      if (base_code(c) >= 0) out.push_back(c);
    }
  }
  return !out.empty();
}

// Squiggle with variable dwell. cv == 0 reproduces the fixed-width generator exactly,
// which is what every earlier measurement in this project used.
std::vector<std::int16_t> signal_with_dwell(const std::vector<float>& levels,
                                           std::uint32_t k, const char* dna,
                                           std::size_t len, std::uint32_t spe,
                                           float noise_pa, float dwell_cv,
                                           float skip_rate, std::uint64_t seed) {
  std::vector<std::int16_t> raw;
  if (len < k) return raw;
  raw.reserve((len - k + 1) * spe * 2);
  std::mt19937_64 rng(seed);
  std::normal_distribution<float> noise(0.0f, noise_pa * kPaToAdc);
  std::uniform_real_distribution<float> unit(0.0f, 1.0f);

  // Lognormal dwell with the requested mean and coefficient of variation. Lognormal
  // rather than normal because dwell is positive and right-skewed, which is what makes
  // the long holds that do the damage.
  const double cv = static_cast<double>(dwell_cv);
  const double sigma2 = std::log(1.0 + cv * cv);
  const double mu = std::log(static_cast<double>(spe)) - 0.5 * sigma2;
  std::lognormal_distribution<double> dwell(mu, std::sqrt(sigma2));

  const std::uint64_t mask = (k >= 32) ? ~0ULL : ((1ULL << (2 * k)) - 1);
  std::uint64_t kmer = 0;
  std::uint32_t have = 0;
  for (std::size_t i = 0; i < len; ++i) {
    const int c = base_code(dna[i]);
    if (c < 0) { have = 0; continue; }
    kmer = ((kmer << 2) | static_cast<std::uint64_t>(c)) & mask;
    if (++have < k) continue;
    if (skip_rate > 0.0f && unit(rng) < skip_rate) continue;  // fast translocation
    std::uint32_t d = spe;
    if (dwell_cv > 0.0f) {
      const double x = dwell(rng);
      d = static_cast<std::uint32_t>(std::lround(std::max(1.0, x)));
      if (d > 8 * spe) d = 8 * spe;  // a pore block, not a dwell
    }
    const float level = levels[kmer] * kPaToAdc;
    for (std::uint32_t t = 0; t < d; ++t) {
      raw.push_back(
          static_cast<std::int16_t>(std::clamp(level + noise(rng), -32000.0f, 32000.0f)));
    }
  }
  return raw;
}

struct ReadResult {
  std::uint32_t best_votes = 0;
  std::int64_t best_diag = 0;
};

// Same path the daemon runs: chunk, scale once from the first chunk, accumulate votes
// through the shared routine.
ReadResult vote_like_the_daemon(const mru::MinimizerIndex& idx,
                              const std::vector<std::int16_t>& raw,
                              const mru::QuantConfig& cfg, int probes,
                              mru::ProbeScratch& scratch,
                              mru::ScalingScratch& scaling_scratch,
                              std::vector<std::int64_t>& diags,
                              std::size_t max_chunks) {
  ReadResult r;
  mru::ChannelVotes votes;
  votes.reset();
  const std::size_t chunk_samples = kChunkBases * cfg.samples_per_event;
  const std::size_t need = cfg.samples_per_event * cfg.events_per_key;
  mru::SignalScaling scaling{};
  bool have_scaling = false;
  std::uint64_t dropped = 0;

  for (std::size_t c = 0; c < max_chunks; ++c) {
    const std::size_t off = c * chunk_samples;
    if (off >= raw.size()) break;
    const std::size_t len = std::min(chunk_samples, raw.size() - off);
    if (len < need) break;
    const std::span<const std::int16_t> chunk(raw.data() + off, len);
    if (!have_scaling) {
      scaling = mru::scaling_from_samples(chunk, scaling_scratch);
      if (!scaling.valid()) break;
      have_scaling = true;
    }
    (void)mru::match_signal(idx, chunk, scaling, cfg, scratch, probes);
    (void)mru::accumulate_chunk_votes(scratch, votes, diags, dropped,
                                      len / cfg.samples_per_event);
  }
  r.best_votes = votes.best(&r.best_diag);
  return r;
}

}  // namespace

int main(int argc, char** argv) {
  if (argc < 3) {
    std::printf("usage: %s <model.tsv> <reference.fa> [reads] [noise_pA] [chunks]\n",
                argv[0]);
    return 2;
  }
  const std::size_t n_reads = argc > 3 ? std::strtoul(argv[3], nullptr, 10) : 300;
  const float noise_pa = argc > 4 ? std::strtof(argv[4], nullptr) : 1.5f;
  const std::size_t max_chunks = argc > 5 ? std::strtoul(argv[5], nullptr, 10) : 10;

  std::vector<float> levels;
  if (!load_model_tsv(argv[1], levels)) {
    std::printf("could not load model %s\n", argv[1]);
    return 1;
  }
  std::string dna;
  if (!load_fasta_acgt(argv[2], dna)) {
    std::printf("could not load reference %s\n", argv[2]);
    return 1;
  }
  mru::PoreModel model;
  if (!model.load_levels(levels)) {
    std::printf("model load failed\n");
    return 1;
  }
  const std::uint32_t k = model.k();

  std::string shuffled = dna;
  {
    std::mt19937_64 rng(20261005);
    std::shuffle(shuffled.begin(), shuffled.end(), rng);
  }

  const mru::QuantConfig cfg;  // frozen 3 x 14
  const int probes = mru::kDefaultProbeBudget;

  std::vector<mru::QEvent> ref_events;
  if (!model.reference_to_events(dna, cfg, ref_events)) {
    std::printf("reference_to_events failed\n");
    return 1;
  }
  std::vector<mru::SeedHash> all_seeds, minimizers;
  mru::hash_all_keys(ref_events, cfg, all_seeds);
  mru::select_minimizers(all_seeds, cfg.minimizer_window, minimizers);
  mru::MinimizerIndex idx;
  idx.build(minimizers);

  std::printf("frozen geometry %u x %u = %u-bit keys, window %u, %u samples/event\n",
              cfg.bits_per_event, cfg.events_per_key, cfg.key_bits(),
              cfg.minimizer_window, cfg.samples_per_event);
  std::printf("reference %zu bases, %zu reads per cell, %zu chunks, noise %.1f pA\n",
              dna.size(), n_reads, max_chunks, static_cast<double>(noise_pa));
  std::printf("\ndwell CV 0.00 with skip 0%% is the generator every earlier measurement "
              "in this project used.\nPublished R10 dwell variability sits around "
              "CV 0.3-0.5.\n\n");

  std::printf("%8s %6s | %-26s | %-14s | %s\n", "dwellCV", "skip", "ON votes",
              "OFF votes", "zero-FP threshold and yield");
  const float cvs[] = {0.0f, 0.1f, 0.2f, 0.3f, 0.5f};
  const float skips[] = {0.0f, 0.02f};

  mru::ProbeScratch scratch;
  mru::ScalingScratch scaling_scratch;
  const std::size_t biggest = max_chunks * kChunkBases * cfg.samples_per_event * 2;
  scratch.reserve_for(biggest, cfg, probes);
  scaling_scratch.reserve(biggest);
  std::vector<std::int64_t> diags;
  diags.reserve(mru::kDiagCapacity);

  // Generous enough that variable dwell cannot run the read short of max_chunks.
  const std::size_t read_bases = max_chunks * kChunkBases * 2 + k + 1;
  if (dna.size() < read_bases + 2 * k) {
    std::printf("reference too short\n");
    return 1;
  }
  const std::size_t span = dna.size() - read_bases - 2 * k;

  for (float skip : skips) {
    for (float cv : cvs) {
      std::vector<std::size_t> on_votes, off_votes;
      std::size_t diag_ok = 0;
      for (std::size_t r = 0; r < n_reads; ++r) {
        const std::size_t d = k + span * (r + 1) / (n_reads + 1);
        const auto raw = signal_with_dwell(levels, k, dna.data() + d, read_bases,
                                           cfg.samples_per_event, noise_pa, cv, skip,
                                           5000 + r);
        if (raw.empty()) continue;
        const ReadResult v = vote_like_the_daemon(idx, raw, cfg, probes, scratch,
                                                 scaling_scratch, diags, max_chunks);
        on_votes.push_back(v.best_votes);
        // Tolerance of 2 events, as elsewhere. Under variable dwell the true diagonal
        // drifts, so this counts reads whose winner is still essentially right.
        if (v.best_votes > 0 &&
            std::llabs(v.best_diag - static_cast<std::int64_t>(d)) <= 2) {
          ++diag_ok;
        }
      }
      for (std::size_t r = 0; r < n_reads; ++r) {
        const std::size_t d = k + span * (r + 1) / (n_reads + 1);
        const auto raw = signal_with_dwell(levels, k, shuffled.data() + d, read_bases,
                                           cfg.samples_per_event, noise_pa, cv, skip,
                                           90000 + r);
        if (raw.empty()) continue;
        const ReadResult v = vote_like_the_daemon(idx, raw, cfg, probes, scratch,
                                                 scaling_scratch, diags, max_chunks);
        off_votes.push_back(v.best_votes);
      }
      if (on_votes.empty() || off_votes.empty()) continue;

      std::sort(on_votes.begin(), on_votes.end());
      std::sort(off_votes.begin(), off_votes.end());
      const std::size_t off_max = off_votes.back();
      const std::size_t t0 = off_max + 1;
      std::size_t tp = 0;
      for (std::size_t v : on_votes) {
        if (v >= t0) ++tp;
      }
      const double tpr =
          100.0 * static_cast<double>(tp) / static_cast<double>(on_votes.size());
      // What the SHIPPED threshold would do, which is what actually matters.
      std::size_t tp5 = 0, fp5 = 0;
      for (std::size_t v : on_votes) {
        if (v >= 5) ++tp5;
      }
      for (std::size_t v : off_votes) {
        if (v >= 5) ++fp5;
      }

      std::printf("%8.2f %5.0f%% | med %3zu p05 %3zu max %4zu | med %2zu max %2zu | "
                  ">=%2zu TPR %5.1f%% | at >=5: TPR %5.1f%% FPR %4.1f%% | diag ok "
                  "%3zu/%zu\n",
                  static_cast<double>(cv), static_cast<double>(skip) * 100.0,
                  on_votes[on_votes.size() / 2], on_votes[on_votes.size() / 20],
                  on_votes.back(), off_votes[off_votes.size() / 2], off_max, t0, tpr,
                  100.0 * static_cast<double>(tp5) / static_cast<double>(on_votes.size()),
                  100.0 * static_cast<double>(fp5) / static_cast<double>(off_votes.size()),
                  diag_ok, on_votes.size());
    }
    std::printf("\n");
  }
  return 0;
}
